function Gourdy.HurtAnimation(p1) --[[ HurtAnimation | Line: 322 ]]
	local Config = p1:WaitForChild("Config")
	local BlinkingParts = p1:FindFirstChild("BlinkingParts")
	local list = {}

	if BlinkingParts and #BlinkingParts:GetChildren() > 0 then
		for i, v in ipairs(BlinkingParts:GetChildren()) do
			if v:IsA("ObjectValue") then
				local v1 = v.Value

				if v1 then
					table.insert(list, v1)

					if v1:FindFirstChildWhichIsA("MeshPart") then
						table.insert(list, v1:FindFirstChildWhichIsA("MeshPart"))
					end
				end
			end
		end

		for i, v in ipairs(list) do
			if v:IsA("BasePart") then
				v.TextureID = Config.HurtTexture.Texture
			end
		end

		task.wait(2)

		if p1.Parent == nil then
			return
		end

		for i, v in ipairs(list) do
			if v:IsA("BasePart") then
				v.TextureID = Config.NormalTexture.Texture
			end
		end

		return
	end

	if not p1:FindFirstChild("MainBody") then
		return
	end

	p1.MainBody.TextureID = Config.HurtTexture.Texture

	if p1.MainBody:FindFirstChild("MainBody") then
		p1.MainBody.MainBody.TextureID = Config.HurtTexture.Texture
	end

	task.wait(2)

	if p1.Parent == nil then
		return
	end

	p1.MainBody.TextureID = Config.NormalTexture.Texture

	if not p1.MainBody:FindFirstChild("MainBody") then
		return
	end

	p1.MainBody.MainBody.TextureID = Config.NormalTexture.Texture
end

